    desc: {
      ar: `المتحف المصري بالتحرير هو أقدم وأهم متحف آثار في مصر والشرق الأوسط، ويحتوي على أكبر مجموعة آثار فرعونية في العالم، مما يجعله "ذاكرة مصر القديمة" لأنه يجمع آثار من آلاف السنين في مكان واحد. يقع المتحف في ميدان التحرير بوسط القاهرة، قريبًا جدًا من نهر النيل، وقد اختير هذا الموقع بعناية لأن النيل كان محور الحياة في مصر القديمة، والقاهرة الحديثة نشأت حوله كمركز حكم وتجارة.

بدأت فكرة إنشاء المتحف في منتصف القرن ال19 على يد عالم الآثار الفرنسي "أوجست مارييت" لحماية الآثار المصرية من الضياع والسرقة. تم اعتماد المشروع رسميًا في عهد الخديوي إسماعيل عام 1863، ونُقلت الآثار بين أماكن مختلفة (بولاق – الجيزة – القلعة) قبل أن يُنقل المتحف إلى موقعه الحالي. وُضع حجر الأساس للمبنى الحالي عام 1897 بعد مسابقة دولية فاز بها المهندس الفرنسي مارسيل دورنيون، وافتُتح المتحف رسميًا عام 1902 في عهد الخديوي عباس حلمي الثاني.

المتحف مصمم على الطراز الأوروبي الكلاسيكي (نيوقلاسيك)، بواجهة ضخمة ومدخل رئيسي وقاعات عرض كبيرة منظمة حسب العصور التاريخية. يضم المتحف أكثر من 120,000 قطعة أثرية، من بينها كنوز الملك توت عنخ آمون (أشهر مجموعة في المتحف)، والمومياوات الملكية، وتماثيل الملوك العظام مثل خوفو وخفرع ومنكاورع، وتمثال الملك زوسر، وبردية نارمر (صلاية الملك مينا)، ونسخة من حجر رشيد.

يُعتبر المتحف وثيقة حية لتطور الحضارة المصرية، ومرجعًا أساسيًا للعلماء والباحثين في علم الآثار، ورمزًا ثقافيًا وسياحيًا لمصر. استقبل المتحف اكتشافات ضخمة من سقارة والأقصر ووادي الملوك، وأصبح وجهة أساسية للزوار من جميع أنحاء العالم.

تم افتتاح المتحف المصري الكبير في منطقة الأهرامات عام 2023 لاستيعاب المجموعات الكبيرة، لكن المتحف المصري بالتحرير يظل رمزًا تاريخيًا وثقافيًا هامًا.`,
      zh: `埃及博物馆（解放广场）是埃及和中东最古老、最重要的考古博物馆，收藏了世界上最大的法老文物藏品，被誉为"古埃及的记忆"，因为它将数千年来的文物汇集在一处。博物馆位于开罗市中心的解放广场，紧邻尼罗河，这个选址经过精心考虑，因为尼罗河是古埃及生活的中心，现代开罗围绕它发展成为政府和商业中心。

建立博物馆的想法始于19世纪中叶，由法国考古学家"奥古斯特·马里埃特"提出，旨在保护埃及文物免遭流失和盗窃。该项目于1863年在赫迪夫伊斯梅尔统治期间正式获批，文物在多个地点之间转移（布拉格 - 吉萨 - 城堡），然后博物馆迁至现址。1897年，在国际竞赛之后，由法国建筑师马塞尔·多尔尼翁设计的现有建筑奠基，博物馆于1902年在赫迪夫·阿巴斯·希尔米二世统治期间正式开放。

博物馆采用欧洲古典风格（新古典主义）设计，拥有宏伟的立面、主入口和按历史时期组织的大型展厅。博物馆收藏超过12万件文物，其中包括图坦卡蒙国王的宝藏（博物馆最著名的藏品）、皇家木乃伊、胡夫、哈夫拉和孟卡拉等伟大法老的雕像、左塞尔法老雕像、纳尔迈石板（米纳国王调色板），以及罗塞塔石碑的复制品。

该博物馆被认为是埃及文明发展的活文献，是考古学家的基本参考，也是埃及的文化和旅游象征。博物馆接收了来自萨卡拉、卢克索和帝王谷的重大发现，已成为来自世界各地游客的重要目的地。

大埃及博物馆于2023年在金字塔区开放以容纳大型藏品，但解放广场的埃及博物馆仍然是重要的历史和文化象征。`
    },
