    desc: {
      ar: `معبد مزدوج فريد من نوعه يقع على ضفاف النيل في كوم أمبو بأسوان، جنوب مصر. شُيّد خلال العصر البطلمي بداية من عهد بطليموس السادس وتم استكماله في العصر الروماني. يتميز بتصميمه المتناظر الكامل (Mirror Design) حيث يضم معبدين متماثلين تحت سقف واحد، مكرّسين لعبادة إلهين مختلفين.

النصف الجنوبي خُصص للإله سوبك — إله التمساح والخصوبة — بينما النصف الشمالي خُصص للإله حورس الأكبر (حور ور). يجمع المعبد بين الدين والعلم، حيث يحتوي على نقوش طبية نادرة تُعد من أقدم التمثيلات للأدوات الجراحية في التاريخ.

يقع المعبد على الضفة الشرقية لنهر النيل فوق ربوة مرتفعة لحمايته من الفيضان، كما كان موقعه مهمًا دينيًا وعمليًا لارتباطه بالنيل كمصدر للحياة وسهولة وصول الزوار والقوافل.

يُعد نموذجًا مميزًا للعمارة البطلمية، ويعكس سياسة البطالمة في كسب المصريين دينيًا. وقد تعرض لعوامل طبيعية مثل فيضان النيل والزلازل، بالإضافة إلى إعادة استخدام أحجاره في عصور لاحقة، قبل أن يتم ترميمه حديثًا.

معنى الاسم: "كوم" تعني التل، و"أمبو" مشتقة من "نوبت" المصرية القديمة وتعني الذهب، ليصبح المعنى "المدينة الذهبية".`,

      zh: `科翁坡神庙是一座独特的双重神庙，位于阿斯旺尼罗河畔。始建于托勒密时代，并在罗马时期完成。其完全对称的设计使其在同一屋顶下供奉两位神灵。

南半部分供奉索贝克神，北半部分供奉荷鲁斯神。神庙结合宗教与科学，拥有世界上最早的医疗器械雕刻之一。

神庙建在尼罗河东岸的高地上，以防洪水，同时也是宗教和交通的重要地点。

它是托勒密建筑的典范，并反映了托勒密王朝的宗教政策。神庙曾遭受洪水和地震破坏，后被修复。名称意为“黄金之城”。`
    },

