    desc: {
      ar: `يُعد معبد فيلة من أجمل وأكمل المعابد المصرية القديمة. بدأ تشييده الملك بطليموس الثاني في العصر اليوناني، وساهم في بنائه العديد من ملوك البطالمة لاحقاً. كان أهم مركز لعبادة الإلهة إيزيس في مصر، ويتميز بموقعه الفريد وسط مياه النيل وبنقوشه الدينية الغنية التي تروي أسطورة إيزيس وأوزيريس.\n\nاختير هذا الموقع لأن المصريين القدماء اعتبروا الجزيرة مكاناً مقدساً، ووجوده في منتصف النيل أعطاه أهمية دينية كبيرة. استمر استخدامه كمعبد حتى القرن السادس الميلادي، وتم تفكيكه ونقله بالكامل إلى جزيرة أجيليكا خلال حملة اليونسكو لإنقاذه من الغرق بسبب بناء السد العالي.`,
      zh: `菲莱神庙是最美丽、最完整的古埃及神庙之一。由托勒密二世在希腊时代开始建造，随后多位托勒密国王参与扩建。它是埃及最重要的伊西斯女神崇拜中心，以其在尼罗河中独特的地理位置和讲述伊西斯与奥西里斯神话的丰富宗教浮雕而闻名。\n\n古埃及人认为该岛是神圣的，位于尼罗河中央赋予了它极大的宗教意义。它一直作为神庙使用到公元6世纪，后来在联合国教科文组织的拯救行动中被完全拆除并搬迁至阿吉利卡岛，以免被阿斯旺高坝的洪水淹没。`
    },
