        '神庙曾被沙土掩埋了几个世纪，上面甚至建起了一个村庄，直到1860年被奥古斯特·马里埃特重新发现。',
        '该神庙每年都会迎接哈索尔女神从丹达拉出发的旅程，以庆祝“美好相遇节”和神圣婚姻。',
