        'يحتوي على 7 أقداس (مقاصير) متجاورة في صف واحد، مخصصة للملك سيتي الأول، بتاح، رع حور آختي، آمون رع، أوزوريس، إيزيس، وحورس.',
        'قائمة ملوك أبيدوس (أهم كنوز المعبد) تضم 76 ملكاً مصرياً من عصر مينا حتى رمسيس الأول، مع استبعاد مقصود لملوك الهكسوس وإخناتون.',
        'الأوزيريون هو بناء ضخم تحت الأرض مبني بكتل جرانيتية يصل وزن بعضها إلى 60 طناً، يمثل المقبرة الرمزية لأوزوريس.',
