        '包含一排7个相邻的圣所，分别供奉塞提一世、普塔赫、拉-哈拉赫提、阿蒙-拉、奥西里斯、伊西斯和荷鲁斯。',
        '阿拜多斯国王列表（神庙最重要的宝藏）包含从美尼斯时代到拉美西斯一世的76位埃及国王，并有意排除了喜克索斯和阿肯那顿。',
