    desc: {
      ar: `في قلب الصحراء الغربية، وعلى بُعد مئات الكيلومترات من صخب المدن، تختبئ واحة سيوة كواحدة من أكثر الوجهات سحرًا وغموضًا في العالم. هنا، لا تسمع سوى همس الرياح بين النخيل، ولا ترى سوى امتداد الرمال الذهبية التي تعانق السماء.

سيوة ليست مجرد واحة، بل تجربة متكاملة تعيد تعريف الهدوء، حيث تلتقي الأسطورة بالحقيقة منذ أن كانت موطنًا لوحي الإله آمون، وحتى أصبحت اليوم وجهة للنخبة الباحثة عن الصفاء.

منذ آلاف السنين، احتلت سيوة مكانة فريدة بفضل معبد آمون (معبد الوحي)، أحد أهم مراكز التنبؤ الديني في العالم القديم. في عام 331 ق.م، زارها الإسكندر الأكبر وأعلن الكهنة أنه ابن آمون، مما عزز شرعيته كحاكم.

تقع الواحة جنوب غرب مرسى مطروح، وتحيط بها بيئة طبيعية مذهلة تشمل بحيرات ملحية فيروزية، آلاف أشجار النخيل والزيتون، الكثبان الرملية التابعة لبحر الرمال العظيم، وتكوينات صخرية وجبال تاريخية.

هذه العزلة الجغرافية صنعت عالماً خاصاً بسيوة، بعيداً عن أي تأثيرات حضرية حديثة، وجعلتها واحدة من أنقى البيئات الطبيعية والثقافية في مصر.`,

      zh: `在西部沙漠的中心，距离城市喧嚣数百公里，隐藏着锡瓦绿洲，它是世界上最神秘和迷人的地方之一。在这里，你只能听到棕榈树间的风声，只能看到无尽的金色沙丘。

锡瓦不仅是一片绿洲，而是一种完整的体验，在这里神话与现实交织。从作为阿蒙神神谕的圣地，到如今成为追求宁静与纯净的人们的目的地。

数千年来，锡瓦因阿蒙神庙（神谕神庙）而具有重要地位。公元前331年，亚历山大大帝来到这里，被宣布为阿蒙之子，从而巩固了其统治合法性。

绿洲位于马特鲁港西南部，周围环绕着盐湖、成千上万的棕榈树和橄榄树、大沙海的沙丘以及历史悠久的山脉。

这种地理隔离使锡瓦成为一个独特的世界，远离现代城市的影响。`
    },

