      zh: `沙姆沙伊赫是埃及乃至世界最重要的旅游城市之一，位于红海亚喀巴湾与苏伊士湾交汇处。\n\n建于1968年，迅速发展成为拥有200多家度假村的国际城市，被称为“和平之城”。`
