    desc: {
      ar: `تُعد مدينة الإسكندرية واحدة من أهم وأشهر المدن في مصر، وتُلقب بـ "عروس البحر الأبيض المتوسط" لما تتمتع به من موقع ساحلي مميز وجمال طبيعي فريد. وهي ثاني أهم مدينة في مصر بعد القاهرة، وكانت تُعد العاصمة القديمة للبلاد ومركزًا رئيسيًا للحضارة والثقافة عبر العصور.\n\nتأسست المدينة على يد الإسكندر الأكبر المقدوني عام 332 قبل الميلاد، فعندما دخل مصر وجد قرية صغيرة تُدعى "راقودة" على ساحل البحر المتوسط وأمامها جزيرة "فاروس"، فقرر إنشاء مدينة جديدة لتربط بينهما لتصبح مدينة عظيمة تحمل اسمه وعاصمة لمصر. بُنيت لتحقيق أهداف استراتيجية كمركز عالمي للتجارة، وقاعدة عسكرية بحرية، ومركزاً للحضارة الهلنستية التي جمعت بين الثقافة اليونانية وثقافات الشرق ومصر وجعلت المدينة منارة عالمية للعلم والمعرفة.\n\nتعد المدينة من أغنى المدن بالآثار والمقابر والمتاحف والحدائق المتنوعة (المنتزه، الشلالات، أنطونيادس) والمعالم الدينية الهامة (مسجد المرسي أبو العباس، مسجد القائد إبراهيم، الكاتدرائية المرقسية)، بالإضافة لأحيائها وشواطئها الشهيرة كالعجمي، ستانلي، والمعمورة.`,
      zh: `亚历山大市被认为是埃及最重要、最著名的城市之一，由于其独特的沿海位置和独特的自然美景，被称为“地中海新娘”。它是仅次于开罗的埃及第二大重要城市，曾是该国的旧都，也是历代文明和文化的主要中心。\n\n这座城市由马其顿的亚历山大大帝于公元前332年建立。当他进入埃及的时候，在地中海沿岸发现了一个名为“Raqouda”的小村庄，前面是“Pharos”岛，因此他决定建立一座新城市将它们连接起来，成为一座以他的名字命名的伟大城市和埃及首都。它的建立是为了实现战略目标，作为一个全球贸易中心、海军军事基地以及希腊化文明的中心，该文明融合了希腊文化、东方文化和埃及文化，使该城市成为全球科学和知识的灯塔。\n\n这座城市拥有丰富的古迹、墓葬、博物馆、各种花园（蒙塔扎、瀑布、安东尼亚迪斯）和重要的宗教地标（Morsi Abu Al-Abbas清真寺、Qaed Ibrahim清真寺、圣马可大教堂），此外还有其著名的街区和海滩，如阿加米、斯坦利和马穆拉。`
    },
    quote: {
      ar: 'عروس البحر الأبيض المتوسط.. حيث تمتزج الحضارات لتشكل لوحة تاريخية خالدة.',
      zh: '地中海新娘……文明在这里交融，形成一幅永恒的历史画卷。'
    },
