    desc: {
      ar: `لم تكن مكتبة الإسكندرية القديمة هي الوحيدة في العالم القديم، ولكنها كانت الأشهر. أسسها بطليموس الأول كمجمع علمي رائد، واختفت إثر حريق تاريخي على يد يوليوس قيصر عام 48 ق.م.\n\nأما المكتبة الحديثة، فقد انطلق حلم إحيائها عام 1972 بنداء من د. مصطفى العبادي، لتدعمها اليونسكو لاحقاً عام 1987 وتُفتتح رسمياً عام 2002. تعد المكتبة أول مكتبة رقمية في القرن الواحد والعشرين، ومركزاً للدراسة والحوار يضم التراث المصري والإنساني بأكثر من ثمانية ملايين كتاب بلغات متنوعة (العربية، الإنجليزية، الفرنسية، وعدة لغات نادرة).\n\nتضم المكتبة 7 مكتبات متخصصة (المواد السمعية والبصرية، طه حسين للمكفوفين، الطفل، النشء، الميكروفيلم، الخرائط، والكتب النادرة) بالإضافة لـ 4 متاحف (الآثار، المخطوطات، السادات، تاريخ العلوم)، وقبة سماوية، ومركزاً دولياً للمؤتمرات وقاعة استكشافات.`,
      zh: `古亚历山大图书馆并不是古代世界唯一的图书馆，但它是最著名的。它由托勒密一世建立，作为一个领先的科学中心，后在公元前48年被尤利乌斯·凯撒的大火摧毁。\n\n至于现代图书馆，复兴它的梦想始于1972年Mustafa El-Abbadi博士的呼吁，随后在1987年得到了联合国教科文组织的支持，并于2002年正式开放。该图书馆是21世纪第一座数字图书馆，也是一个研究和对话中心，包含埃及和人类文化遗产，拥有超过800万本各种语言（阿拉伯语，英语，法语等罕见语言）的藏书。\n\n图书馆包括7个专门图书馆（视听材料，为盲人设立的塔哈·侯赛因图书馆，儿童，青年，缩微胶卷，地图和珍本图书），以及4个博物馆（文物，手稿，萨达特，科学历史），一个天文馆、一个国际会议中心和一个探索大厅。`
    },
    quote: { ar: 'نافذة العالم على مصر، ونافذة مصر على العالم.. إحياء لأسطورة المعرفة.', zh: '世界了解埃及的窗口，埃及了解世界的窗口……知识传奇的复兴。' },
