const museums = [
  { n: { ar: 'المتحف المصري بالتحرير', zh: '埃及博物馆（解放广场）' }, loc: { ar: 'ميدان التحرير، القاهرة', zh: '开罗解放广场' }, desc: { ar: 'أقدم وأهم متحف آثار في مصر والشرق الأوسط، يحتوي على أكبر مجموعة آثار فرعونية في العالم (+120,000 قطعة). يضم كنوز توت عنخ آمون الكاملة والمومياوات الملكية.', zh: '埃及和中东最古老、最重要的考古博物馆，收藏世界上最大的法老文物藏品（超过12万件）。藏有完整的图坦卡蒙宝藏和皇家木乃伊。' }, tags: { ar: ['مصر القديمة', 'توت عنخ آمون', 'المومياوات الملكية', 'التحرير'], zh: ['古埃及', '图坦卡蒙', '皇家木乃伊', '解放广场'] } },
  { n: { ar: 'المتحف المصري الكبير', zh: '大埃及博物馆' }, loc: { ar: 'الجيزة، بجوار الأهرامات', zh: '吉萨，金字塔旁' }, desc: { ar: 'أضخم متحف في العالم مكرس لحضارة واحدة، افتُتح عام 2023 لاستيعاب المجموعات الكبيرة. يضم الهرم الثلاثي لمنكاورع في قلبه وكنوز توت عنخ آمون.', zh: '世界上最大的专注于单一文明的博物馆，于2023年开放以容纳大型藏品。中心收藏孟卡拉金字塔和图坦卡蒙宝藏。' }, tags: { ar: ['الأهرامات', 'منكاورع', 'توت عنخ آمون', '2023'], zh: ['金字塔', '孟卡拉', '图坦卡蒙', '2023'] } },
  { n: { ar: 'متحف الحضارة المصرية', zh: '埃及文明博物馆' }, loc: { ar: 'الفسطاط، القاهرة', zh: '开罗福斯塔特' }, desc: { ar: 'يُعد المتحف وجهة أساسية لفهم تطور الحضارة المصرية عبر العصور. يضم قاعة المومياوات الملكية التي تضم 22 مومياء ملكية من مختلف العصور.', zh: '该博物馆是理解埃及文明历代发展的主要目的地。藏有包含22具历代皇家木乃伊的皇家木乃伊厅。' }, tags: { ar: ['المومياوات الملكية', 'الفسطاط', 'حضارة مصرية', '22 مومياء'], zh: ['皇家木乃伊', '福斯塔特', '埃及文明', '22具木乃伊'] } },
  { n: { ar: 'متحف قلعة صلاح الدين', zh: '萨拉丁城堡博物馆' }, loc: { ar: 'صلاح الدين، القاهرة', zh: '开罗萨拉丁' }, desc: { ar: 'يضم المتحف مجموعة نادرة من الأسلحة والدروع والعملات من العصر الإسلامي. يقع داخل قلعة صلاح الدين الأيوبي التاريخية.', zh: '博物馆收藏伊斯兰时代罕见的武器、盔甲和钱币藏品。位于历史悠久的萨拉丁城堡内。' }, tags: { ar: ['العصر الأيوبي', 'أسلحة إسلامية', 'قلعة صلاح الدين'], zh: ['阿尤布时代', '伊斯兰武器', '萨拉丁城堡'] } },
  { n: { ar: 'متحف الكنيسة المعلقة', zh: '悬空教堂博物馆' }, loc: { ar: 'الفتيح، القاهرة', zh: '开罗法蒂赫' }, desc: { ar: 'يضم المتحف القبطي الواقع داخل الكنيسة المعلقة مجموعة من المخطوطات القبطية والأيقونات والأقمشة والعناصر الفنية النادرة من العصور الوسطى.', zh: '位于悬空教堂内的科普特博物馆收藏中世纪科普特手稿、圣像、织物和稀有艺术元素。' }, tags: { ar: ['التراث القبطي', 'مخطوطات', 'أيقونات', 'الكنيسة المعلقة'], zh: ['科普特遗产', '手稿', '圣像', '悬空教堂'] } }
];